rgin-top:20px}.stat-row{display:grid;grid-template-columns:28px 1fr auto;align-items:center;column-gap:9px}.stat-icon{height:28px;width:28px;border-radius:8px;display:grid;place-items:center;font-size:13px;background:#f2eee4}.stat-row:nth-child(2) .stat-icon{background:#f9eee8}.stat-row:nth-child(3) .stat-icon{background:#edf2e8}.stat-row:nth-child(4) .stat-icon{background:#eef0f7}.stat-name{font-size:11px;color:#5d6a61;font-weight:600}.stat-value{font-size:11px;color:#66776a;font-weight:700}.stat-track{height:4px;background:#f0f0e9;border-radius:5px;grid-column:2/4;margin-top:6px;overflow:hidden}.stat-fill{height:100%;border-radius:5px;background:#83a47e;transition:width .5s}.stat-row:nth-child(2) .stat-fill{background:#d9a07b}.stat-row:nth-child(3) .stat-fill{background:#88a777}.stat-row:nth-child(4) .stat-fill{background:#8c91b4}.choices-heading{margin:2px 2px 12px}.choice-count{font-size:10px;color:#959d95}.action-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.action-card{background:var(--card);border:1px solid #ebeae2;border-radius:9px;padding:13px 12px 12px;text-align:left;min-height:105px;transition:.18s;position:relative}.action-card:hover{border-color:#b4c6af;transform:translateY(-2px);box-shadow:0 6px 14px rgba(49,83,56,.08)}.action-card.done{opacity:.55;cursor:default;transform:none}.action-icon{display:grid;place-items:center;width:29px;height:29px;background:#edf3eb;border-radius:8px;font-size:15px;margin-bottom:9px}.action-card:nth-child(3n+2) .action-icon{background:#faf0e7}.action-card:nth-child(3n) .action-icon{background:#f0eff7}.action-card strong{display:block;font-size:11px;margin-bottom:4px}.action-card small{font-size:9px;color:#90988f;line-height:1.4;display:block}.action-card .action-result{color:#57805b;font-weight:600}.year-controls{display:flex;align-items:center;justify-content:space-between;padding:15px 17px}.year-controls>div{display:flex;align-items:center;gap:11px}.calendar-icon{height:31px;width:31px;display:grid;pla